/**
 * Regenerates src/fonts.generated.ts from fonts/*.woff (Sarabun, SIL OFL 1.1; see fonts/OFL.txt).
 * The package is pure (no file reads at run time), so the fonts travel inside the source as base64.
 *   pnpm --filter @sds/escpos fonts:embed
 */
import { readFileSync, writeFileSync } from 'node:fs';

const FILES = [
  ['thaiRegular', 'sarabun-thai-400-normal.woff'],
  ['thaiBold', 'sarabun-thai-700-normal.woff'],
  ['latinRegular', 'sarabun-latin-400-normal.woff'],
  ['latinBold', 'sarabun-latin-700-normal.woff'],
] as const;

const lines = [
  '// Generated by scripts/embed-fonts.ts from fonts/*.woff. Do not edit by hand.',
  '// Sarabun, Copyright 2018 The Sarabun Project Authors, SIL Open Font License 1.1 (fonts/OFL.txt).',
];
for (const [name, file] of FILES) {
  const base64 = readFileSync(new URL(`../fonts/${file}`, import.meta.url)).toString('base64');
  lines.push(`export const ${name}Base64 = '${base64}';`);
}
writeFileSync(new URL('../src/fonts.generated.ts', import.meta.url), `${lines.join('\n')}\n`);
